valid_if:
=IF(USERROLE() = "ADMIN",
 (SM_Today_User[Shipment No] + 
 SELECT(ข้อมูล งานRT[Shipment (รับคืน)], [วันที่เข้ารับ] = TODAY())),
 IF([ข้อมูลการแจ้งปั ญหา] = "ไม่มีในจุดส่งงานวันนี้ ไม่สามารถเข้ารับงานคืนให้ ได้",
 SELECT(ข้อมูลงานRT[Shipment (รับคืน)], 
 AND([Email พนักงาน] = USEREMAIL(), [วันที่เข้ารับ] = TODAY())
 ),
 SM_Today_User[Shipment No]
 )
)

=UNIQUE(
 IF(USERROLE() ="ADMIN",
 SELECT(ตารางงานประจำวัน[Invoice No], [ShipmentNo] = [_THISROW].[Shipment No]) +
 SELECT(ข้อมูลงานRT[เลขที่เอกสารรับคืน], [Shipment (รับคืน)] = [_THISROW].[ShipmentNo]),
 IF([ข้อมูลการแจ้งปั ญหา] = "ไม่มีในจุดส่งงานวันนี้ ไม่สามารถเข้ารับงานคืนให้ได้",
 SELECT(ข้อมูลงานRT[เลขที่เอกสารรับคืน],
 AND(
 [Shipment (รับคืน)] = [_THISROW].[ShipmentNo],
 [Email พนักงาน] = USEREMAIL(),
 [วันที่เข้ารับ] =TODAY()
 )
 ),
 SELECT(SM_Today_User[Invoice No], 
AND(
 [Shipment No] = [_THISROW].[Shipment No],
[DeliveryStatus] <> "จัดส่งเรียบร้อย",
 NOT(IN([Invoice No],SELECT(แจ้งปั ญหาระหว่างวัน[Invoice No], [Shipment No] =[_THISROW].[Shipment No])))
 )
 )
 )
 ) 
 + [_THISROW].[Invoice No]
) -LIST("")
